<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { CdcMessage, CdcMessageBox } from './ui/feedback'
import { LockKeyhole, Save } from 'lucide-vue-next'
import { api } from '../api'

const props=defineProps({modelValue:Boolean,taskId:{type:Number,required:true},subscription:{type:Object,default:null}})
const emit=defineEmits(['update:modelValue','saved'])
const loading=ref(false),saving=ref(false),options=ref(null),targetTables=ref([]),targetTopics=ref([])
const form=reactive({name:'',description:'',targetId:null,tables:[]})
const step=ref(0)
const task=computed(()=>options.value?.task||{}), source=computed(()=>options.value?.source||{}), targets=computed(()=>options.value?.targets||[])
const selectedTarget=computed(()=>targets.value.find(item=>item.id===form.targetId)), isKafka=computed(()=>selectedTarget.value?.targetType==='KAFKA')
const targetKeys=computed(()=>targetTables.value.map(item=>({...item,key:[item.schema,item.table].filter(Boolean).join('.')})))
watch(()=>props.modelValue,open=>{if(open){step.value=0;load()}},{immediate:true})
function next(){if(step.value===0&&(!form.name.trim()||!form.targetId))return CdcMessage.warning('请填写订阅名称并选择目标连接');if(step.value===1&&form.tables.some(row=>!row.targetTable||!sourceKeys(row).every(key=>row.columns[key])))return CdcMessage.warning('请完成所有目标表和主键映射');step.value++}
function disabled(){return {enabled:false,sourceTimeColumn:null,targetTimeColumn:null,fields:[]}}
function fresh(sourceTable){return {sourceTaskTableId:sourceTable.id,targetSchema:null,targetTable:'',targetSelection:'',columns:{},includeOperation:true,operationColumn:'_cdc_operation',includeCapturedAt:true,capturedAtColumn:'_cdc_captured_at',capturedAtFormat:'TIMESTAMP',operationValues:{CREATE:'1',UPDATE:'2',DELETE:'3',READ:'4'},reconciliation:disabled(),source:sourceTable}}
async function load(){loading.value=true;try{options.value=await api(`/tasks/${props.taskId}/subscription-options`);Object.assign(form,{name:props.subscription?.name||'',description:props.subscription?.description||'',targetId:props.subscription?.targetId||null,tables:(options.value.tables||[]).map(sourceTable=>{const row=fresh(sourceTable),binding=props.subscription?.tables.find(item=>item.sourceTaskTableId===sourceTable.id);if(binding){Object.assign(row,binding.mapping,{source:sourceTable,sourceTaskTableId:sourceTable.id,subscriptionTableId:binding.id,targetSelection:[binding.mapping.targetSchema,binding.mapping.targetTable].filter(Boolean).join('.')});row.columns={...binding.mapping.columns};row.reconciliation=JSON.parse(JSON.stringify(binding.mapping.reconciliation||disabled()))}return row})});targetTables.value=[];targetTopics.value=[];if(form.targetId){if(isKafka.value)targetTopics.value=await api(`/targets/${form.targetId}/topics`);else targetTables.value=await api(`/targets/${form.targetId}/tables`)}}catch(e){CdcMessage.error(e.message)}finally{loading.value=false}}
async function targetChanged(){targetTables.value=[];targetTopics.value=[];form.tables.forEach(row=>{row.targetSchema=null;row.targetTable='';row.targetSelection='';row.columns={}});if(!form.targetId)return;try{if(isKafka.value)targetTopics.value=await api(`/targets/${form.targetId}/topics`);else targetTables.value=await api(`/targets/${form.targetId}/tables`)}catch(e){CdcMessage.error(e.message)}}
function targetColumns(row){if(isKafka.value)return row.source?.sourceColumns||Object.keys(row.source?.columns||{});const item=targetKeys.value.find(x=>x.table===row.targetTable&&(x.schema||null)===(row.targetSchema||null));return item?.columns||[]}
function sourceColumns(row){return row.source?.sourceColumns||Object.keys(row.source?.columns||{})}
function sourceKeys(row){return row.source?.keyColumns||[]}
function targetChangedForRow(row,value){if(isKafka.value){row.targetSchema=null;row.targetTable=value}else{const meta=targetKeys.value.find(x=>x.key===value);if(!meta)return;row.targetSchema=meta.schema||null;row.targetTable=meta.table}row.columns=Object.fromEntries(sourceColumns(row).filter(x=>targetColumns(row).includes(x)).map(x=>[x,x]))}
function setMapping(row,sourceColumn,targetColumn){if(targetColumn)row.columns[sourceColumn]=targetColumn;else delete row.columns[sourceColumn]}
function timeColumns(row){return sourceColumns(row).filter(column=>/DATE|TIME|YEAR/i.test(String(row.source?.sourceColumnDetails?.find(x=>x.name===column)?.type||''))&&row.columns[column])}
function enableReconciliation(row,value){row.reconciliation.enabled=value;if(!value)row.reconciliation=disabled()}
function changeTime(row){row.reconciliation.targetTimeColumn=row.columns[row.reconciliation.sourceTimeColumn]||null}
function selectedReconColumns(row){return (row.reconciliation.fields||[]).map(field=>field.sourceColumn)}
function changeReconColumns(row,columns){row.reconciliation.fields=columns.map(column=>({sourceColumn:column,targetColumn:row.columns[column],logicalType:'OTHER',metrics:['NULL_RATE']}))}
function submitRows(){return form.tables.map(({source,targetSelection,...row})=>row)}
async function submit(){
  if(!form.name.trim())return CdcMessage.warning('请输入订阅名称')
  if(!form.targetId)return CdcMessage.warning('请选择目标连接')
  for(const row of form.tables){if(!row.targetTable)return CdcMessage.warning(`请选择 ${row.source.sourceTable} 的目标表`);if(!Object.keys(row.columns).length)return CdcMessage.warning(`${row.source.sourceTable} 至少配置一个字段映射`);if(!sourceKeys(row).every(key=>row.columns[key]))return CdcMessage.warning(`${row.source.sourceTable} 的主键必须完整映射`);if(row.reconciliation.enabled&&(!row.reconciliation.sourceTimeColumn||!row.reconciliation.targetTimeColumn||!row.reconciliation.fields.length))return CdcMessage.warning(`${row.source.sourceTable} 的数据核对配置不完整`)}
  if(props.subscription)try{await CdcMessageBox.confirm('修改投递映射将重新初始化当前目标。采用主键覆盖，不清空目标表；源端已不存在的历史行不会自动删除。','确认重新初始化')}catch{return}
  saving.value=true;try{const result=await api(`/tasks/${props.taskId}/subscriptions${props.subscription?'/'+props.subscription.id:''}`,{method:props.subscription?'PUT':'POST',body:JSON.stringify({name:form.name,description:form.description,targetId:form.targetId,tables:submitRows()})});CdcMessage.success(props.subscription?'投递映射已更新，正在重新初始化':`目标订阅已创建，正在自动初始化（#${result.id}）`);emit('update:modelValue',false);emit('saved')}catch(e){CdcMessage.error(e.message)}finally{saving.value=false}
}
</script>

<template>
  <cdc-modal :model-value="modelValue" width="min(1060px,95vw)" top="4vh" :title="props.subscription?'编辑投递映射':'新增目标订阅'" @close="emit('update:modelValue',false)">
    <cdc-steps :active="step"><cdc-step title="目标连接"/><cdc-step title="表映射与核对"/><cdc-step title="确认初始化"/></cdc-steps>
    <div v-loading="loading" class="subscription-wizard">
      <cdc-alert type="info" :closable="false" show-icon title="源端由当前同步任务统一管理" description="新增目标只配置目标库表、字段映射和数据核对；不会新建源连接或第二条 CDC 采集链路。"/>
      <section class="source-summary"><div class="section-heading"><LockKeyhole :size="17"/><strong>任务源端（只读）</strong><span>任务 #{{task.id}}</span></div><div class="source-grid"><div><label>源连接</label><strong>{{source.name||'-'}}</strong></div><div><label>同步模式</label><strong>{{task.syncMode==='FULL_INCREMENTAL'?'全量 + 增量':'仅增量'}}</strong></div><div><label>源表</label><strong>{{form.tables.length}} 张</strong></div></div></section>
      <cdc-form v-if="step===0" label-position="top"><div class="two-cols"><cdc-form-item label="订阅名称" required><cdc-input v-model="form.name" :disabled="!!props.subscription" placeholder="例如：订单同步到 StarRocks"/></cdc-form-item><cdc-form-item label="说明"><cdc-input v-model="form.description" :disabled="!!props.subscription"/></cdc-form-item></div><cdc-form-item label="目标连接" required><cdc-select v-model="form.targetId" :disabled="!!props.subscription" filterable style="width:100%" placeholder="选择目标连接" @change="targetChanged"><cdc-option v-for="target in targets" :key="target.id" :label="target.name+' · '+target.targetType" :value="target.id"/></cdc-select></cdc-form-item></cdc-form>
      <cdc-collapse v-if="step===1" accordion class="mapping-list"><cdc-collapse-item v-for="(row,index) in form.tables" :key="row.sourceTaskTableId" :name="index"><template #title><strong>{{[row.source.sourceDatabase,row.source.sourceSchema,row.source.sourceTable].filter(Boolean).join('.')}}</strong><span class="collapse-meta">主键：{{sourceKeys(row).join(', ')||'-'}}</span></template><div class="mapping-card"><cdc-form label-position="top"><cdc-form-item :label="isKafka?'目标 Topic':'目标表'" required><cdc-select v-if="isKafka" v-model="row.targetTable" filterable style="width:100%" placeholder="选择 Topic" @change="value=>targetChangedForRow(row,value)"><cdc-option v-for="topic in targetTopics" :key="topic" :label="topic" :value="topic"/></cdc-select><cdc-select v-else :model-value="row.targetSelection" filterable style="width:100%" placeholder="选择目标表" @change="value=>{row.targetSelection=value;targetChangedForRow(row,value)}"><cdc-option v-for="item in targetKeys" :key="item.key" :label="item.key" :value="item.key"/></cdc-select></cdc-form-item></cdc-form><cdc-table :data="sourceColumns(row).map(column=>({column}))" border size="small" max-height="210"><cdc-table-column prop="column" label="源字段" min-width="200"><template #default="{row:field}"><span class="mono">{{field.column}}</span><cdc-tag v-if="sourceKeys(row).includes(field.column)" size="small" type="warning">主键</cdc-tag></template></cdc-table-column><cdc-table-column label="目标字段" min-width="250"><template #default="{row:field}"><cdc-select :model-value="row.columns[field.column]||''" clearable filterable style="width:100%" @change="value=>setMapping(row,field.column,value)"><cdc-option v-for="column in targetColumns(row)" :key="column" :label="column" :value="column"/></cdc-select></template></cdc-table-column></cdc-table><div class="extension-grid"><cdc-switch v-model="row.includeOperation" active-text="写入 CDC 操作类型"/><cdc-input v-if="row.includeOperation" v-model="row.operationColumn" placeholder="目标操作列"/><cdc-switch v-model="row.includeCapturedAt" active-text="写入 CDC 抓取时间"/><div v-if="row.includeCapturedAt" class="inline-fields"><cdc-input v-model="row.capturedAtColumn" placeholder="目标抓取时间列"/><cdc-select v-model="row.capturedAtFormat"><cdc-option label="数据库时间戳" value="TIMESTAMP"/><cdc-option label="ISO-8601" value="ISO8601"/></cdc-select></div></div><div class="reconciliation"><div class="reconciliation-head"><strong>数据核对</strong><cdc-switch :disabled="isKafka" :model-value="row.reconciliation.enabled" active-text="启用" @change="value=>enableReconciliation(row,value)"/></div><div v-if="row.reconciliation.enabled" class="two-cols"><cdc-form label-position="top"><cdc-form-item label="业务变更时间字段"><cdc-alert v-if="!timeColumns(row).length" type="warning" title="当前已映射字段中没有日期时间字段"/><cdc-select v-else v-model="row.reconciliation.sourceTimeColumn" style="width:100%" @change="changeTime(row)"><cdc-option v-for="column in timeColumns(row)" :key="column" :label="column" :value="column"/></cdc-select></cdc-form-item></cdc-form><cdc-form label-position="top"><cdc-form-item label="目标映射字段"><cdc-input :model-value="row.reconciliation.targetTimeColumn||''" disabled/></cdc-form-item></cdc-form><cdc-form label-position="top" class="reconciliation-fields"><cdc-form-item label="核数字段"><cdc-select :model-value="selectedReconColumns(row)" multiple collapse-tags style="width:100%" @change="value=>changeReconColumns(row,value)"><cdc-option v-for="column in sourceColumns(row).filter(column=>row.columns[column]&&column!==row.reconciliation.sourceTimeColumn)" :key="column" :label="column" :value="column"/></cdc-select></cdc-form-item></cdc-form></div><cdc-alert v-if="row.reconciliation.enabled" title="保存后可在该目标订阅内单独发起或查看数据核对。" type="info" :closable="false" show-icon/></div></div></cdc-collapse-item></cdc-collapse>
      <section v-if="step===2" class="source-summary"><h3>{{form.name}}</h3><p>目标：{{selectedTarget?.name}}</p><p>将为 {{form.tables.length}} 张源表执行目标专属全量初始化。</p><div v-for="row in form.tables" :key="row.sourceTaskTableId" class="mono">{{row.source.sourceTable}} → {{row.targetTable}} · {{Object.keys(row.columns).length}} 个字段</div></section>
    </div>
    <template #footer><cdc-button @click="emit('update:modelValue',false)">取消</cdc-button><cdc-button v-if="step>0" @click="step--">上一步</cdc-button><cdc-button v-if="step<2" type="primary" @click="next">下一步</cdc-button><cdc-button v-else type="primary" :loading="saving" @click="submit"><Save :size="15"/>{{props.subscription?'保存并重新初始化':'创建并初始化'}}</cdc-button></template>
  </cdc-modal>
</template>
